package br.com.admeclesial.application.projeto;
import br.com.admeclesial.domain.financeiro.*; import br.com.admeclesial.domain.organizacao.OrganizacaoEclesial; import br.com.admeclesial.domain.projeto.*; import br.com.admeclesial.infrastructure.persistence.financeiro.*; import br.com.admeclesial.infrastructure.persistence.organizacao.OrganizacaoEclesialRepository; import br.com.admeclesial.infrastructure.persistence.projeto.*; import org.junit.jupiter.api.Test; import org.junit.jupiter.api.extension.ExtendWith; import org.mockito.*; import org.mockito.junit.jupiter.MockitoExtension; import java.math.BigDecimal; import java.util.*; import static org.junit.jupiter.api.Assertions.*; import static org.mockito.ArgumentMatchers.*; import static org.mockito.Mockito.*;
@ExtendWith(MockitoExtension.class) class ProjetoApplicationServiceTest { @Mock ProjetoRepository repo; @Mock OrganizacaoEclesialRepository org; @Mock ItemOrcamentoRepository itens; @Mock OrcamentoRepository orcamentos; @Mock FonteRecursoProjetoRepository fontes;
@Test void deveCriarProjetoPlanejado(){var o=new OrganizacaoEclesial();setId(o,1L);o.setAtivo(true);var u=UUID.randomUUID();when(org.findByUuid(u)).thenReturn(Optional.of(o));when(repo.save(any())).thenAnswer(i->i.getArgument(0));var s=new ProjetoApplicationService(repo,org,itens,orcamentos,fontes);var p=s.criar(new ProjetoRequest(u,null,TipoProjeto.OBRA,"Telhado",null,null,null,new BigDecimal("1000")));assertEquals(StatusProjeto.PLANEJADO,p.getStatus());assertEquals(1L,p.getOrganizacaoEclesialId());}
@Test void naoPermiteItemOrcamentoDeOutraOrganizacao(){var o=new OrganizacaoEclesial();setId(o,1L);o.setAtivo(true);var item=new ItemOrcamento();setId(item,2L);item.setOrcamentoId(5L);var orc=new Orcamento();orc.setOrganizacaoEclesialId(9L);var ou=UUID.randomUUID();var iu=UUID.randomUUID();when(org.findByUuid(ou)).thenReturn(Optional.of(o));when(itens.findByUuid(iu)).thenReturn(Optional.of(item));when(orcamentos.findById(5L)).thenReturn(Optional.of(orc));var s=new ProjetoApplicationService(repo,org,itens,orcamentos,fontes);assertThrows(IllegalArgumentException.class,()->s.criar(new ProjetoRequest(ou,iu,TipoProjeto.PROJETO,"Projeto",null,null,null,null)));}
private static void setId(Object o,long id){try{var f=o.getClass().getDeclaredField("id");f.setAccessible(true);f.set(o,id);}catch(Exception e){throw new RuntimeException(e);}} }
